// Command yamlprobe checks where yaml.v3 puts a trailing comment on a
// sequence item that has no value, versus one that does.
package main

import (
	"fmt"

	"gopkg.in/yaml.v3"
)

const src = `write_set:
  - # placeholder
  - a.go # note
  - "b.go" # quoted
open_questions:
  -
  - # bare with comment
`

func walk(n *yaml.Node, path string) {
	fmt.Printf("%-10s kind=%-9s tag=%-7s value=%-8q line_comment=%-16q head=%q\n",
		path, kindName(n.Kind), n.Tag, n.Value, n.LineComment, n.HeadComment)
	for i, c := range n.Content {
		walk(c, fmt.Sprintf("%s/%d", path, i))
	}
}

func kindName(k yaml.Kind) string {
	switch k {
	case yaml.DocumentNode:
		return "document"
	case yaml.SequenceNode:
		return "seq"
	case yaml.MappingNode:
		return "map"
	case yaml.ScalarNode:
		return "scalar"
	case yaml.AliasNode:
		return "alias"
	}
	return "?"
}

func main() {
	var doc yaml.Node
	if err := yaml.Unmarshal([]byte(src), &doc); err != nil {
		fmt.Println("unmarshal:", err)
		return
	}
	walk(&doc, "")

	var parsed struct {
		WriteSet      []string `yaml:"write_set"`
		OpenQuestions []string `yaml:"open_questions"`
	}
	if err := yaml.Unmarshal([]byte(src), &parsed); err != nil {
		fmt.Println("typed unmarshal:", err)
		return
	}
	fmt.Printf("\ndecoded write_set=%q open_questions=%q\n", parsed.WriteSet, parsed.OpenQuestions)
}

